302:     fun searchAndRank(words: List<WordEntity>, query: String): List<MatchResult> {
303:         val trimmed = query.trim()
304:         if (trimmed.isBlank()) {
305:             return words.map { MatchResult(it, 0, "", isBestMatch = false) }
306:         }
307: 
308:         val results = words.mapNotNull { scoreWord(it, trimmed) }
309:             .sortedWith(
310:                 compareByDescending<MatchResult> { it.score }
311:                     .thenByDescending { it.word.examAppearances }
312:                     .thenBy { it.word.korean.length }
313:             )
314: 
315:         if (results.isEmpty()) return emptyList()
316: 
317:         // Mark the single top score as best match if it has high confidence (score >= 85)
318:         val highestScore = results.first().score
319:         return results.mapIndexed { index, item ->
320:             if (index == 0 && highestScore >= 80) {
321:                 item.copy(isBestMatch = true)
322:             } else {
323:                 item
