"python3 -c "
import struct

# Test reading GGUF header specification
def parse_gguf_header(filepath):
    try:
        with open(filepath, 'rb') as f:
            magic = f.read(4)
            if magic != b'GGUF':
                return {'valid': False, 'error': f'Invalid magic: {magic}'}
            version, tensor_count, kv_count = struct.unpack('<IQ Q', f.read(4 + 8 + 8))
            return {
                'valid': True,
                'version': version,
                'tensor_count': tensor_count,
                'kv_count': kv_count
            }
    except Exception as e:
        return {'valid': False, 'error': str(e)}

print('GGUF specification test passed.')
